    /**
     * Tests getting all LineItems.
     *
     * @return    Collection
     */
    public List<LineItem> testGetAll() throws Throwable {
    LOGGER.info( "LineItemTest:testGetAll() - Retrieving Collection of LineItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LineItem : " );
    List<LineItem> collection  = null;

    try {
        // call the static get method on the LineItemService
        collection = service.getAllLineItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LineItem currEntity  = null;
            Iterator<LineItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLineItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

